import SwiftUI

/// Glett's colours: the CSS custom properties of css/style.css:2-21, as colour sets in Assets.xcassets/Colors with the
/// light and dark values (generated by apple/scripts/icons-export.mjs). Use `Color.glett.accent` or, where a
/// ShapeStyle is expected, `.glett.accent`.
struct GlettPalette: Sendable {
    /// `--bg`
    var bg: Color { named("bg") }
    /// `--panel`
    var panel: Color { named("panel") }
    /// `--text`
    var text: Color { named("text") }
    /// `--muted`
    var muted: Color { named("muted") }
    /// `--line`
    var line: Color { named("line") }
    /// `--accent`
    var accent: Color { named("accent") }
    /// `--accent-2`
    var accent2: Color { named("accent-2") }
    /// `--good`
    var good: Color { named("good") }
    /// `--mid`
    var mid: Color { named("mid") }
    /// `--bad`
    var bad: Color { named("bad") }
    /// `--sun`
    var sun: Color { named("sun") }
    /// `--moon`
    var moon: Color { named("moon") }
    /// `--cloud`
    var cloud: Color { named("cloud") }
    /// `--rain`
    var rain: Color { named("rain") }
    /// `--snow`
    var snow: Color { named("snow") }
    /// `--bolt`
    var bolt: Color { named("bolt") }
    /// `--warn`
    var warn: Color { named("warn") }
    /// `--cloud-top`
    var cloudTop: Color { named("cloud-top") }
    /// `--cloud-bot`
    var cloudBot: Color { named("cloud-bot") }
    /// `--moon-mid`
    var moonMid: Color { named("moon-mid") }
    /// `--moon-dark`
    var moonDark: Color { named("moon-dark") }
    /// `--summary` (the summary panel background)
    var summary: Color { named("summary") }
    /// `--prob` (the probability row background)
    var prob: Color { named("prob") }

    /// Text on an accent-filled button (`.btn.primary`, css/style.css:41, 250): white in light, #0b1220 in dark.
    var onAccent: Color {
        Color(UIColor { $0.userInterfaceStyle == .dark ? UIColor(red: 11 / 255, green: 18 / 255, blue: 32 / 255, alpha: 1) : .white })
    }

    /// Every token by its CSS name, for previews and checks.
    static let tokens = ["bg", "panel", "text", "muted", "line", "accent", "accent-2", "good", "mid", "bad", "sun", "moon",
                         "cloud", "rain", "snow", "bolt", "warn", "cloud-top", "cloud-bot", "moon-mid", "moon-dark",
                         "summary", "prob"]

    /// The colour for a CSS token name (`"accent-2"`).
    func named(_ token: String) -> Color { Color("Colors/\(token)", bundle: .main) }
}

extension Color {
    static let glett = GlettPalette()
}

extension ShapeStyle where Self == Color {
    static var glett: GlettPalette { GlettPalette() }
}

#Preview("Palette") {
    ScrollView {
        LazyVGrid(columns: [GridItem(.adaptive(minimum: 96), spacing: 8)], spacing: 8) {
            ForEach(GlettPalette.tokens, id: \.self) { token in
                VStack(spacing: 4) {
                    RoundedRectangle(cornerRadius: 8)
                        .fill(Color.glett.named(token))
                        .stroke(Color.glett.line)
                        .frame(height: 44)
                    Text(verbatim: token).font(.caption).foregroundStyle(.glett.muted)
                }
            }
        }
        .padding()
    }
    .background(Color.glett.bg)
}
